mapper.select:
select count(1) as warnCount, credit_code as uscc from risk_control_warn_monitor
and credit_code in
#{item}
and warn_level = #{warnLevel}
group by credit_code

select count(distinct(credit_code)) from risk_control_warn_monitor
where data_time = date_add(curdate(),interval -1 day) and
credit_code not in (select distinct(credit_code) from risk_control_warn_monitor where data_time < date_add(curdate(),interval -1 day));

select a.id as id, a.title as title, a.chi_name as chiName, a.credit_code as creditCode, a.data_time as dataTime, a.warn_code as warnCode, a.warn_level as warnLevel, a.link_address as linkAddress, a.handle_status as handle_status, c.belong_dept_id as belongDeptId, a.data_source as dataSource from risk_control_warn_monitor a left join client c on a.credit_code = c.usc_code
and a.chi_name like CONCAT('%',#{param.chiName},'%')
and a.credit_code like CONCAT('%',#{param.creditCode},'%')
and a.warn_code like CONCAT('%',#{param.warnCode},'%')
and a.title like CONCAT('%',#{param.title},'%')
and c.belong_dept_id = #{param.belongDeptId}
and a.warn_level in
#{item}
and a.handle_status = #{param.handleStatus}
and c.belong_dept_id in
#{item}
and a.id in
#{item}
order by a.create_time desc

select count(1) from risk_control_warn_monitor
where create_time >= curdate()

    and warn_level = #{warnLevel}

select count(1) from risk_control_warn_monitor where update_time >= curdate()
and handle_status = 'HANDLED'

    and warn_level = #{warnLevel}

SELECT
id,
title,
credit_code,
data_time
FROM risk_control_warn_monitor
WHERE

    (
    title = #{param.title}
    AND credit_code = #{param.creditCode}
    AND data_time = #{param.dataTime}
    )
